                continue
            universe, R = formal_context(cnf)
            min_rank_value = min_rank(universe, R)
            width_value = width(cnf)
            results.append((min_rank_value, math.log(width_value)))

    if len(results) < 30:
        return {
            "metric_name": "correlation",
